impl Solution{pub fn add_operators(s:String,t:i32)->Vec<String>{fn f(s:&str,p:usize,v:i64,last:i64,e:String,t:i64,o:&mut Vec<String>){if p==s.len(){if v==t{o.push(e)}return}let mut n=0i64;for i in p..s.len(){if i>p&&s.as_bytes()[p]==b'0'{break}n=n*10+(s.as_bytes()[i]-b'0')as i64;let x=&s[p..=i];if p==0{f(s,i+1,n,n,x.into(),t,o)}else{f(s,i+1,v+n,n,format!("{}+{}",e,x),t,o);f(s,i+1,v-n,-n,format!("{}-{}",e,x),t,o);f(s,i+1,v-last+last*n,last*n,format!("{}*{}",e,x),t,o);}}}let mut o=vec![];f(&s,0,0,0,String::new(),t as i64,&mut o);o}}
